// Loan payoff: type what you owe, the yearly rate in % and what you pay each month, then press
// Calculate; it shows the months until it is paid off and the interest paid in all.
// icon: loop 4 6 20 6 20 20 4 20 line 4 10 20 10 line 8 3 8 8 line 16 3 16 8
state owed = "";
state rate = "";
state pay = "";
state months = 0;
state paid = 0;           // the interest paid in all
state never = false;

fn num(s: string) -> int { return parse(s, 0); }

// Month by month: the interest added, then the payment taken off. A payment that does not
// cover the interest never pays it off.
fn calc() {
  let owe = num(owed);
  months = 0;
  paid = 0;
  repeat 600 {
    let i = owe * num(rate) / 1200;
    if owe > 0 && i < num(pay) {
      paid += i;
      owe += i - num(pay);
      months += 1;
    }
  }
  never = owe > 0;
}

