state winner = 0;          // 0 playing, 1 X, 2 O, 3 a draw
// The eight lines, three squares each: rows, columns, diagonals.
state lines = [0, 1, 2, 3, 4, 5, 6, 7, 8, 0, 3, 6, 1, 4, 7, 2, 5, 8, 0, 4, 8, 2, 4, 6];

// Who has won: 1 X, 2 O, 3 a full board with no line, 0 nobody yet.
fn won() -> int {
  for k in 0..8 {
    let a = board[lines[k * 3]];
    if a != 0 && a == board[lines[k * 3 + 1]] && a == board[lines[k * 3 + 2]] { return a; }
  }
  for i in 0..9 {
    if board[i] == 0 { return 0; }
  }
  return 3;
}

fn status() -> string {
  if winner == 1 { return "X wins"; }
  if winner == 2 { return "O wins"; }
  if winner == 3 { return "Draw"; }
  if turn == 1 { return "X to move"; }
  return "O to move";
}

// Each square a silver tile; X a red cross, O a blue disc, drawn over its middle.
