    if board[i] == 2 { sprite([".444.", "44444", "44444", "44444", ".444."], px + 10, py + 10, 4); }
  }
}

fn play(i: int) {
  if winner == 0 && board[i] == 0 {
    board[i] = turn;
    turn = 3 - turn;
    winner = won();
  }
}

