// Tic-tac-toe against the computer: you are X (red) and move first by tapping a square; the
// computer, O (blue), answers at once. New game starts over.
// icon: line 2 7 10 15 line 10 7 2 15 ring 17 11 4
state board = [0; 9];      // 0 empty, 1 X (you), 2 O (the computer)
state winner = 0;          // 0 playing, 1 you, 2 the computer, 3 a draw
// The eight lines, three squares each: rows, columns, diagonals.
state lines = [0, 1, 2, 3, 4, 5, 6, 7, 8, 0, 3, 6, 1, 4, 7, 2, 5, 8, 0, 4, 8, 2, 4, 6];
state corners = [0, 2, 6, 8];

// Who has won: 1 X, 2 O, 3 a full board with no line, 0 nobody yet.
fn won() -> int {
  for k in 0..8 {
    let a = board[lines[k * 3]];
    if a != 0 && a == board[lines[k * 3 + 1]] && a == board[lines[k * 3 + 2]] { return a; }
  }
  for i in 0..9 {
    if board[i] == 0 { return 0; }
  }
  return 3;
}

// Whether p's mark on the empty square i would complete a line of p's.
fn completes(i: int, p: int) -> bool {
  for k in 0..8 {
    let a = lines[k * 3];
    let b = lines[k * 3 + 1];
    let c = lines[k * 3 + 2];
    let n = 0;
    if board[a] == p { n += 1; }
    if board[b] == p { n += 1; }
    if board[c] == p { n += 1; }
    if n == 2 && (a == i || b == i || c == i) { return true; }
  }
  return false;
}

// The computer's square: one that wins, else one that blocks, else the middle, else the first
// free corner, else the first free square; the first row by row when several do.
fn pick() -> int {
  for i in 0..9 {
    if board[i] == 0 && completes(i, 2) { return i; }
  }
  for i in 0..9 {
    if board[i] == 0 && completes(i, 1) { return i; }
  }
  if board[4] == 0 { return 4; }
  for k in 0..4 {
    if board[corners[k]] == 0 { return corners[k]; }
  }
  for i in 0..9 {
    if board[i] == 0 { return i; }
  }
  return 0;
}

fn status() -> string {
  if winner == 1 { return "You win"; }
  if winner == 2 { return "You lose"; }
  if winner == 3 { return "Draw"; }
  return "Your move";
}

fn play(i: int) {
  if winner != 0 || board[i] != 0 { return; }
  board[i] = 1;
  winner = won();
  if winner == 0 {
    board[pick()] = 2;
    winner = won();
  }
}

// Each square a silver tile; X a red cross, O a blue disc, drawn over its middle.
fn scene() {
  for i in 0..9 {
    let px = (i % 3) * 40;
    let py = (i / 3) * 40;
    rect(px + 1, py + 1, 38, 38, 7);
    if board[i] == 1 { sprite(["1...1", ".1.1.", "..1..", ".1.1.", "1...1"], px + 10, py + 10, 4); }
    if board[i] == 2 { sprite([".444.", "44444", "44444", "44444", ".444."], px + 10, py + 10, 4); }
  }
}

