// Reaction timer: press Start, wait for the red circle to turn green, then tap as fast as you
// can. Tapping while it is red is too soon.
// icon: fill 14 2 5 14 11 14 9 22 19 10 13 10
state phase = 0;          // 0 no try, 1 red: waiting, 2 green: timing
state left = 0;           // ms until it turns green
state ms = 0;             // ms since it turned green
state last = -1;          // the last try's time; -1 none yet
state best = -1;
state soon = false;
state first = true;       // the first try waits 2 seconds
state speed = 0;          // ms a tick; 0 while no try runs

fn start() {
  if first { left = 2000; } else { left = 1000 + random(201) * 10; }
  first = false;
  ms = 0;
  soon = false;
  phase = 1;
  speed = 10;
}

every speed {
  if phase == 1 {
    left -= 10;
    if left <= 0 { phase = 2; }
  } else {
    ms += 10;
  }
}

fn react() {
  if phase == 1 { soon = true; }
  if phase == 2 {
    last = ms;
    if best < 0 || ms < best { best = ms; }
  }
  phase = 0;
  speed = 0;
}

fn tint() -> int {
  if phase == 1 { return 1; }
  if phase == 2 { return 2; }
  return 8;
}

fn scene() {
  circle(80, 60, 50, tint());
  if soon { text("Too soon", 80, 60, 16, 9); }
}

fn shown(t: int) -> string {
  if t < 0 { return "-"; }
  return t + " ms";
}

