// Reaction test: space (or a tap) starts a round; when the panel turns green, press space as
// fast as you can. Three rounds, then your average.
// icon: ring 12 13 8 line 12 13 12 8 line 10 3 14 3
state phase = 0;              // 0 between rounds, 1 red: waiting, 2 green: timing
state times = [0; 0];         // this game's rounds, in ms
state delays = [2000, 3000, 1000]; // the first game's waits
state games = 0;              // games begun
state left = 0;               // ms until it turns green
state ms = 0;                 // ms since it turned green
state soon = false;
state speed = 0;              // ms a tick; 0 while no round runs

// A round's wait, from its start: the first game's are set, later ones random.
fn wait() {
  if games == 1 { left = delays[len(times)]; } else { left = 1000 + random(301) * 10; }
  ms = 0;
  phase = 1;
  speed = 10;
}

fn go() {
  if phase == 0 {
    if games == 0 || len(times) == 3 {
      clear(times);
      games += 1;
    }
    soon = false;
    wait();
  } else if phase == 1 {
    soon = true;
    wait();
  } else {
    push(times, ms);
    phase = 0;
    speed = 0;
  }
}

every speed {
  if phase == 1 {
    left -= 10;
    if left <= 0 { phase = 2; }
  } else {
    ms += 10;
  }
}

fn sum() -> int {
  let s = 0;
  for i in 0..len(times) { s += times[i]; }
  return s;
}

fn tint() -> int {
  if phase == 1 { return 1; }
  if phase == 2 { return 2; }
  return 8;
}

fn scene() {
  rect(10, 10, 140, 100, tint());
  if soon { text("Too soon", 80, 60, 16, 9); }
}

