// Tetris with a score: the arrows or the buttons move and turn the piece, space or Drop drops it;
// rows cleared together score more. The next piece shows below.
// icon: fill 3 9 9 9 9 15 3 15 fill 9 9 15 9 15 15 9 15 fill 15 9 21 9 21 15 15 15 fill 9 3 15 3 15 9 9 9
state shapes = [0, 1, 2, 3, 0, 1, 4, 5, 1, 4, 5, 6, 1, 2, 4, 5, 0, 1, 5, 6, 0, 4, 5, 6, 2, 4, 5, 6];
state tints = [6, 3, 5, 2, 1, 4, 7];   // I O T S Z J L: each piece's four squares in a 4 x 4 box
state names = ["I", "O", "T", "S", "Z", "J", "L"];
state opening = [1, 1, 1, 1, 1, 0, 0, 1];   // the very first game's first pieces
state points = [0, 100, 300, 500, 800];     // for 0 to 4 rows at once
state board = [0; 200];   // the landed blocks, 10 a row: 0 empty, else a color
state piece = 0;
state next = 0;
state dealt = 0;          // pieces dealt this game
state games = 0;
state turn = 0;           // quarter turns clockwise
state px = 3;             // the piece's left and top
state py = 0;
state score = 0;
state speed = 0;          // ms a row; 0 while no game runs
state over = false;

// Square k of piece t turned r times: across (a 0) or down (a 1), before shifting.
fn raw(t: int, r: int, k: int, a: int) -> int {
  let cx = shapes[t * 4 + k] % 4;
  let cy = shapes[t * 4 + k] / 4;
  repeat r {
    let n = 0 - cy;
    cy = cx;
    cx = n;
  }
  if a == 0 { return cx; }
  return cy;
}

// The same, shifted so the piece's left and top are 0.
fn part(t: int, r: int, k: int, a: int) -> int {
  let m = 9;
  for j in 0..4 { m = min(m, raw(t, r, j, a)); }
  return raw(t, r, k, a) - m;
}

// The board square of the piece's square k.
fn spot(k: int) -> int { return (py + part(piece, turn, k, 1)) * 10 + px + part(piece, turn, k, 0); }

fn fits(r: int, ox: int, oy: int) -> bool {
  for k in 0..4 {
    let c = ox + part(piece, r, k, 0);
    let w = oy + part(piece, r, k, 1);
    if c < 0 || c >= 10 || w < 0 || w >= 20 { return false; }
    if board[w * 10 + c] != 0 { return false; }
  }
  return true;
}

// The piece after this one: the opening's in the first game, else at random.
fn deal() {
  if games == 1 && dealt < len(opening) { next = opening[dealt]; } else { next = random(7); }
  dealt += 1;
}

fn appear() {
  piece = next;
  deal();
  turn = 0;
  px = 3;
  py = 0;
  if !fits(0, px, py) {
    speed = 0;
    over = true;
  }
}

// Full rows go, top to bottom, the rows above each coming down one; then the score.
fn clearRows() {
  let n = 0;
  for w in 0..20 {
    let full = true;
    for c in 0..10 {
      if board[w * 10 + c] == 0 { full = false; }
    }
    if full {
      for k in 0..w {
        for c in 0..10 { board[(w - k) * 10 + c] = board[(w - k - 1) * 10 + c]; }
      }
      for c in 0..10 { board[c] = 0; }
      n += 1;
    }
  }
  score += points[n];
}

fn land() {
  for k in 0..4 { board[spot(k)] = tints[piece]; }
  clearRows();
  appear();
}

fn start() {
  for i in 0..200 { board[i] = 0; }
  games += 1;
  dealt = 0;
  score = 0;
  over = false;
  speed = 600;
  deal();
  appear();
}

