fn rotate() { if speed > 0 && fits((turn + 1) % 4, px, py) { turn = (turn + 1) % 4; } }
fn lower() { if speed > 0 && fits(turn, px, py + 1) { py += 1; } }
fn drop() {
  if speed > 0 {
