// Minesweeper: tap a square to open it; Flag switches taps to flagging and back. Open every
// square without a mine to win. 9 x 9 and 10 mines.
// icon: dot 12 13 6 line 12 4 12 22 line 3 13 21 13 line 6 7 18 19 line 18 7 6 19
state mines = [0; 81];    // 1 where a mine is
state shown = [0; 81];    // 0 hidden, 1 open, 2 flagged
state first = [1, 6, 26, 30, 45, 52, 58, 73, 77, 80];   // the first game's mines
state placed = false;     // mines go down at a game's first tap
state game = 0;
state over = 0;           // 0 playing, 1 lost, 2 won
state flagging = false;

fn mine(c: int, r: int) -> int {
  if c < 0 || c >= 9 || r < 0 || r >= 9 { return 0; }
  return mines[r * 9 + c];
}

// The mines around square i (and on it).
fn near(i: int) -> int {
  let n = 0;
  for d in 0..9 { n += mine(i % 9 + d % 3 - 1, i / 9 + d / 3 - 1); }
  return n;
}

// The first game's mines where given; later ones on 10 squares at random.
fn lay() {
  if game == 0 {
    for k in 0..10 { mines[first[k]] = 1; }
  } else {
    for n in 0..10 {
      let k = random(81 - n);
      for i in 0..81 {
        if mines[i] == 0 {
          if k == 0 { mines[i] = 1; }
          k -= 1;
        }
      }
    }
  }
  placed = true;
}

// Opens the neighbours of each open square with no mine around, and on.
fn flood(start: int) {
  let todo = [start];
  let at = 0;
  repeat 81 {
    if at < len(todo) {
      let i = todo[at];
      at += 1;
      if near(i) == 0 {
        for d in 0..9 {
          let c = i % 9 + d % 3 - 1;
          let r = i / 9 + d / 3 - 1;
          if c >= 0 && c < 9 && r >= 0 && r < 9 {
            if shown[r * 9 + c] == 0 {
              shown[r * 9 + c] = 1;
              push(todo, r * 9 + c);
            }
          }
        }
      }
    }
  }
}

fn won() -> bool {
  for i in 0..81 {
    if mines[i] == 0 && shown[i] != 1 { return false; }
  }
  return true;
}

fn tap(i: int) {
  if over != 0 { return; }
  if flagging {
    if shown[i] == 0 { shown[i] = 2; } else if shown[i] == 2 { shown[i] = 0; }
    return;
  }
  if shown[i] != 0 { return; }
  if !placed { lay(); }
  shown[i] = 1;
  if mines[i] == 1 {
    over = 1;
    return;
  }
  flood(i);
  if won() { over = 2; }
}

fn fresh() {
  for i in 0..81 {
    mines[i] = 0;
    shown[i] = 0;
  }
  placed = false;
  game += 1;
  over = 0;
  flagging = false;
}

// A square 12 units wide: hidden gray, a flag blue, a mine red once lost, else its count.
fn square(i: int) {
  let px = (i % 9) * 12;
  let py = (i / 9) * 12;
  if over == 1 && mines[i] == 1 {
    rect(px, py, 11, 11, 1);
  } else if shown[i] == 0 {
    rect(px, py, 11, 11, 8);
  } else if shown[i] == 2 {
    rect(px, py, 11, 11, 4);
  } else if near(i) > 0 {
    text(near(i), px + 6, py + 6, 9, 9);
  }
}

fn scene() {
  for i in 0..81 { square(i); }
}

fn status() -> string {
  if over == 1 { return "Game over"; }
  if over == 2 { return "You win"; }
  if flagging { return "Tap to flag"; }
  return "Tap to open";
}

