  button "New game" { fresh(); }
}

// Minesweeper with chords: tap to open; Flag switches taps to flagging and back. Tap an opened
// number with as many flags around it to open the rest around it. 8 x 8 and 10 mines.
// icon: dot 12 13 6 line 12 4 12 22 line 3 13 21 13 line 6 7 18 19 line 18 7 6 19
state mines = [0; 64];    // 1 where a mine is
state shown = [0; 64];    // 0 hidden, 1 open, 2 flagged
state first = [2, 15, 24, 28, 29, 39, 50, 53, 56, 62];   // the first game's mines
state placed = false;     // mines go down at a game's first opening
state game = 0;
state over = 0;           // 0 playing, 1 lost, 2 won
state flagging = false;

// Square d (0 to 8) of the three by three around square i; -1 off the board.
fn around(i: int, d: int) -> int {
  let c = i % 8 + d % 3 - 1;
  let r = i / 8 + d / 3 - 1;
  if c < 0 || c >= 8 || r < 0 || r >= 8 { return -1; }
  return r * 8 + c;
}

// The mines around square i.
fn near(i: int) -> int {
  let n = 0;
  for d in 0..9 {
    let j = around(i, d);
    if j >= 0 { n += mines[j]; }
  }
  return n - mines[i];
}

// The flags around square i.
fn flagsNear(i: int) -> int {
  let n = 0;
  for d in 0..9 {
    let j = around(i, d);
    if j >= 0 {
      if shown[j] == 2 { n += 1; }
    }
  }
  return n;
}

fn flags() -> int {
  let n = 0;
  for i in 0..64 {
    if shown[i] == 2 { n += 1; }
  }
  return n;
}

// The first game's mines where given; later ones on 10 squares at random.
fn lay() {
  if game == 0 {
    for k in 0..10 { mines[first[k]] = 1; }
  } else {
    for n in 0..10 {
      let k = random(64 - n);
      for i in 0..64 {
        if mines[i] == 0 {
          if k == 0 { mines[i] = 1; }
          k -= 1;
        }
      }
    }
  }
  placed = true;
}

// Opens the neighbours of each open square with no mine around, and on.
fn flood(start: int) {
  let todo = [start];
  let at = 0;
  repeat 64 {
    if at < len(todo) {
      let i = todo[at];
      at += 1;
      if near(i) == 0 {
        for d in 0..9 {
          let j = around(i, d);
          if j >= 0 {
            if shown[j] == 0 {
              shown[j] = 1;
              push(todo, j);
            }
          }
        }
      }
    }
  }
}

// Opens hidden square i: a mine loses.
fn dig(i: int) {
  if over != 0 || shown[i] != 0 { return; }
  shown[i] = 1;
  if mines[i] == 1 {
    over = 1;
    return;
  }
  flood(i);
}

// An opened number with as many flags around it opens the rest around it.
fn chord(i: int) {
  if near(i) == 0 || flagsNear(i) != near(i) { return; }
  for d in 0..9 {
    let j = around(i, d);
    if j >= 0 { dig(j); }
  }
}

fn won() -> bool {
  for i in 0..64 {
    if mines[i] == 0 && shown[i] != 1 { return false; }
  }
  return true;
}

fn tap(i: int) {
  if over != 0 { return; }
  if flagging {
    if shown[i] == 0 { shown[i] = 2; } else if shown[i] == 2 { shown[i] = 0; }
    return;
  }
  if !placed { lay(); }
  if shown[i] == 1 { chord(i); } else { dig(i); }
  if over == 0 && won() { over = 2; }
}

fn fresh() {
  for i in 0..64 {
    mines[i] = 0;
    shown[i] = 0;
  }
  placed = false;
  game += 1;
  over = 0;
  flagging = false;
}

// A square 12 units wide: hidden gray, a flag blue, a mine red once lost, else its count.
fn square(i: int) {
  let px = (i % 8) * 12;
  let py = (i / 8) * 12;
  if over == 1 && mines[i] == 1 {
    rect(px, py, 11, 11, 1);
  } else if shown[i] == 0 {
    rect(px, py, 11, 11, 8);
  } else if shown[i] == 2 {
    rect(px, py, 11, 11, 4);
  } else if near(i) > 0 {
    text(near(i), px + 6, py + 6, 9, 9);
  }
}

fn scene() {
  for i in 0..64 { square(i); }
}

fn status() -> string {
  if over == 1 { return "Game over"; }
  if over == 2 { return "You win"; }
  if flagging { return "Tap to flag"; }
  return "Tap to open";
}

