// Connect four for two: tap a column to drop a disc, Red then Yellow; four in a line wins.
// icon: ring 7 7 4 dot 17 7 4 dot 7 17 4 ring 17 17 4
state board = [0; 42];    // 7 a row, row 0 at the top: 0 empty, 1 red, 2 yellow
state turn = 1;
state result = 0;         // 0 playing, 1 red won, 2 yellow won, 3 a draw

fn at(c: int, r: int) -> int {
  if c < 0 || c >= 7 || r < 0 || r >= 6 { return 0; }
  return board[r * 7 + c];
}

// Whether the disc at (c, r) starts four of its color, each a step (dc, dr) from the last.
fn four(c: int, r: int, dc: int, dr: int) -> bool {
  let p = at(c, r);
  if p == 0 { return false; }
  for k in 1..4 {
    if at(c + dc * k, r + dr * k) != p { return false; }
  }
  return true;
}

fn winner() -> int {
  for i in 0..42 {
    let c = i % 7;
    let r = i / 7;
    if four(c, r, 1, 0) || four(c, r, 0, 1) || four(c, r, 1, 1) || four(c, r, 1, -1) {
      return board[i];
    }
  }
  return 0;
}

fn full() -> bool {
  for c in 0..7 {
    if board[c] == 0 { return false; }
  }
  return true;
}

// A disc into column c's lowest empty square, if the game goes on and it has room.
fn drop(c: int) {
  if result != 0 { return; }
  for k in 0..6 {
    let i = (5 - k) * 7 + c;
    if board[i] == 0 {
      board[i] = turn;
      turn = 3 - turn;
      result = winner();
      if result == 0 && full() { result = 3; }
      return;
    }
  }
}

fn tint(v: int) -> int {
  if v == 1 { return 1; }
  if v == 2 { return 3; }
  return 0;
}

// Blue boards with holes 20 units apart, each disc in its color.
fn scene() {
  rect(0, 0, 140, 120, 4);
  for i in 0..42 { circle((i % 7) * 20 + 10, (i / 7) * 20 + 10, 8, tint(board[i])); }
}

fn status() -> string {
  if result == 1 { return "Red wins"; }
  if result == 2 { return "Yellow wins"; }
  if result == 3 { return "Draw"; }
  if turn == 1 { return "Red to play"; }
  return "Yellow to play";
}

