// Connect four against the computer: tap a column to drop a red disc; yellow answers at once.
// icon: ring 7 7 4 dot 17 7 4 dot 7 17 4 ring 17 17 4
state board = [0; 42];    // 7 a row, row 0 at the top: 0 empty, 1 mine (red), 2 its (yellow)
state result = 0;         // 0 playing, 1 I won, 2 it won, 3 a draw

fn at(c: int, r: int) -> int {
  if c < 0 || c >= 7 || r < 0 || r >= 6 { return 0; }
  return board[r * 7 + c];
}

// How many of p's discs run on from (c, r), a step (dc, dr) at a time, up to 3.
fn run(c: int, r: int, dc: int, dr: int, p: int) -> int {
  let n = 0;
  for k in 1..4 {
    if n == k - 1 && at(c + dc * k, r + dr * k) == p { n = k; }
  }
  return n;
}

// Whether a disc of p at (c, r) makes four in a line.
fn fours(c: int, r: int, p: int) -> bool {
  if run(c, r, 1, 0, p) + run(c, r, -1, 0, p) >= 3 { return true; }
  if run(c, r, 0, 1, p) + run(c, r, 0, -1, p) >= 3 { return true; }
  if run(c, r, 1, 1, p) + run(c, r, -1, -1, p) >= 3 { return true; }
  return run(c, r, 1, -1, p) + run(c, r, -1, 1, p) >= 3;
}

// The row a disc dropped in column c lands on; -1 when it is full.
fn landing(c: int) -> int {
  for k in 0..6 {
    if board[(5 - k) * 7 + c] == 0 { return 5 - k; }
  }
  return -1;
}

// The leftmost column where a disc of p makes four; -1 if none does.
fn winning(p: int) -> int {
  for c in 0..7 {
    let r = landing(c);
    if r >= 0 {
      if fours(c, r, p) { return c; }
    }
  }
  return -1;
}

// Its column: a win, else a block, else the one nearest the middle with room.
fn choice() -> int {
  let c = winning(2);
  if c < 0 { c = winning(1); }
  let order = [3, 2, 4, 1, 5, 0, 6];
  for k in 0..7 {
    if c < 0 && landing(order[k]) >= 0 { c = order[k]; }
  }
  return c;
}

fn full() -> bool {
  for c in 0..7 {
    if board[c] == 0 { return false; }
  }
  return true;
}

fn put(c: int, p: int) {
  let r = landing(c);
  board[r * 7 + c] = p;
  if fours(c, r, p) { result = p; } else if full() { result = 3; }
}

fn tap(c: int) {
  if result != 0 || landing(c) < 0 { return; }
  put(c, 1);
  if result == 0 { put(choice(), 2); }
}

fn tint(v: int) -> int {
  if v == 1 { return 1; }
  if v == 2 { return 3; }
  return 0;
}

fn scene() {
  rect(0, 0, 140, 120, 4);
  for i in 0..42 { circle((i % 7) * 20 + 10, (i / 7) * 20 + 10, 8, tint(board[i])); }
}

fn status() -> string {
  if result == 1 { return "You win"; }
  if result == 2 { return "Computer wins"; }
  if result == 3 { return "Draw"; }
  return "Your turn: tap a column";
}

