// Breakout: Start, then space or Launch sends the ball up; the arrows, or a tap or a drag, move
// the paddle. Break every brick; three lives.
// icon: fill 3 4 10 4 10 8 3 8 fill 14 4 21 4 21 8 14 8 dot 12 14 2 fill 5 18 19 18 19 22 5 22
state bricks = [1; 35];   // 7 a row, 5 rows from the top: 1 standing
state padx = 55;          // the paddle's left end; it is 30 wide
state bx = 70;            // the ball's middle
state by = 107;
state dx = 0;             // its step across, and down (up when negative)
state dy = 0;
state speed = 0;          // ms a step while the ball flies; 0 while it rests
state score = 0;
state lives = 3;
state playing = false;
state over = 0;           // 0 none yet, 1 lost, 2 won

// The ball back on the paddle's middle, waiting.
fn rest() {
  speed = 0;
  bx = padx + 15;
  by = 107;
}

fn steer(left: int) {
  padx = min(110, max(0, left));
  if speed == 0 { bx = padx + 15; }
}

fn launch() {
  if playing && speed == 0 {
    dx = 0;
    dy = -2;
    speed = 20;
  }
}

fn start() {
  for i in 0..35 { bricks[i] = 1; }
  score = 0;
  lives = 3;
  over = 0;
  playing = true;
  rest();
}

fn standing() -> int {
  let n = 0;
  for i in 0..35 { n += bricks[i]; }
  return n;
}

// The brick at the ball's leading edge breaks and turns it back.
fn hit() {
  let edge = by - 2;
  if dy > 0 { edge = by + 2; }
  if edge >= 10 && edge < 40 {
    let i = ((edge - 10) / 6) * 7 + bx / 20;
    if bricks[i] == 1 {
      bricks[i] = 0;
      dy = 0 - dy;
      score += 1;
      if standing() == 0 {
        over = 2;
        playing = false;
        speed = 0;
      }
    }
  }
}

every speed {
  bx = min(138, max(2, bx + dx));
  by += dy;
  if bx <= 2 || bx >= 138 { dx = 0 - dx; }
  if by <= 2 { dy = 2; }
  hit();
  if dy > 0 && by >= 108 && by <= 112 && bx >= padx && bx <= padx + 30 {
    dy = -2;
    dx = (bx - padx - 15) / 6;
  }
  if by > 124 {
    lives -= 1;
    rest();
    if lives == 0 {
      over = 1;
      playing = false;
    }
  }
}

