// Breakout with a catching paddle: move the paddle under a column (arrows, a tap or a drag), then
// space or Launch sends the ball straight up to break a brick; the paddle catches it coming back.
// icon: fill 3 4 10 4 10 8 3 8 fill 14 4 21 4 21 8 14 8 dot 12 14 2 fill 5 18 19 18 19 22 5 22
state bricks = [1; 21];   // 7 a row, 3 rows from the top: 1 standing
state worth = [3, 2, 1];  // each row's points, from the top
state padx = 55;          // the paddle's left end; it is 30 wide
state by = 107;           // the ball's middle, up and down; across it is padx + 15 or bx
state bx = 70;
state dy = 0;             // its step down (up when negative)
state speed = 0;          // ms a step while the ball flies; 0 while it rests
state score = 0;
state lives = 3;
state playing = false;
state over = 0;           // 0 none yet, 1 lost, 2 won

// The ball back on the paddle's middle, waiting.
fn rest() {
  speed = 0;
  bx = padx + 15;
  by = 107;
}

fn steer(left: int) {
  if playing {
    padx = min(110, max(0, left));
    if speed == 0 { bx = padx + 15; }
  }
}

fn launch() {
  if playing && speed == 0 {
    dy = -2;
    speed = 20;
  }
}

fn start() {
  for i in 0..21 { bricks[i] = 1; }
  score = 0;
  lives = 3;
  over = 0;
  playing = true;
  rest();
}

fn standing() -> int {
  let n = 0;
  for i in 0..21 { n += bricks[i]; }
  return n;
}

// The brick at the ball's top breaks, scores its row's points and sends the ball back down.
fn hit() {
  let edge = by - 2;
  if dy < 0 && edge >= 10 && edge < 28 {
    let i = ((edge - 10) / 6) * 7 + bx / 20;
    if bricks[i] == 1 {
      bricks[i] = 0;
      dy = 2;
      score += worth[i / 7];
    }
  }
}

fn end(how: int) {
  over = how;
  playing = false;
  rest();
}

every speed {
  by += dy;
  if by <= 2 { dy = 2; }
  hit();
  if dy > 0 && by >= 108 && by <= 112 && bx >= padx && bx <= padx + 30 {
    rest();
    if standing() == 0 { end(2); }
  }
  if by > 124 {
    lives -= 1;
    rest();
    if lives == 0 { end(1); }
  }
}

