// Fifteen: tap a tile beside the gap, or press an arrow, to slide it in; put 1 to 15 in order.
// icon: loop 3 3 21 3 21 21 3 21 fill 5 5 11 5 11 11 5 11 fill 13 5 19 5 19 11 13 11 fill 5 13 11 13 11 19 5 19
state tiles = [1, 2, 3, 4, 5, 10, 6, 8, 13, 9, 7, 11, 14, 15, 0, 12];   // row by row; 0 the gap
state moves = 0;

fn gap() -> int {
  for i in 0..16 {
    if tiles[i] == 0 { return i; }
  }
  return 0;
}

fn solved() -> bool {
  for i in 0..15 {
    if tiles[i] != i + 1 { return false; }
  }
  return true;
}

// Whether squares a and b are side by side or one above the other.
fn beside(a: int, b: int) -> bool { return abs(a % 4 - b % 4) + abs(a / 4 - b / 4) == 1; }

fn swap(a: int, b: int) {
  let t = tiles[a];
  tiles[a] = tiles[b];
  tiles[b] = t;
}

// The tile on square i into the gap, if it is right beside it.
fn slide(i: int) {
  let g = gap();
  if solved() || i < 0 || i > 15 || !beside(i, g) { return; }
  swap(i, g);
  moves += 1;
}

// Random slides from the solved order, so it can be solved; one more if it came back solved.
fn shuffle() {
  for i in 0..16 { tiles[i] = (i + 1) % 16; }
  repeat 500 {
    let i = random(16);
    if beside(i, gap()) { swap(i, gap()); }
  }
  if solved() { swap(14, 15); }
  moves = 0;
}

fn scene() {
  for i in 0..16 {
    if tiles[i] != 0 {
      rect((i % 4) * 30 + 1, (i / 4) * 30 + 1, 28, 28, 6);
      text(tiles[i], (i % 4) * 30 + 15, (i / 4) * 30 + 15, 12, 9);
    }
  }
}

on key "left" { slide(gap() + 1); }
on key "right" { slide(gap() - 1); }
on key "up" { slide(gap() + 4); }
on key "down" { slide(gap() - 4); }

