// Fifteen with line slides: tap any tile in line with the gap to slide it and those between;
// tiles in their own square are green. Put 1 to 15 in order.
// icon: loop 3 3 21 3 21 21 3 21 fill 5 5 11 5 11 11 5 11 fill 13 5 19 5 19 11 13 11 fill 5 13 11 13 11 19 5 19
state tiles = [5, 1, 2, 3, 9, 6, 4, 8, 13, 10, 7, 12, 14, 15, 11, 0];   // row by row; 0 the gap
state moves = 0;

fn gap() -> int {
  for i in 0..16 {
    if tiles[i] == 0 { return i; }
  }
  return 0;
}

fn solved() -> bool {
  for i in 0..15 {
    if tiles[i] != i + 1 { return false; }
  }
  return true;
}

// The step from square i one square toward the gap g: 0 if i is not in its row or column.
fn toward(i: int, g: int) -> int {
  if i == g { return 0; }
  if i / 4 == g / 4 {
    if g > i { return 1; }
    return -1;
  }
  if i % 4 == g % 4 {
    if g > i { return 4; }
    return -4;
  }
  return 0;
}

// The tile on square i and those between it and the gap, each one square toward the gap.
fn shift(i: int) {
  let g = gap();
  let d = toward(i, g);
  if d == 0 { return; }
  repeat 3 {
    if g != i {
      tiles[g] = tiles[g - d];
      g -= d;
    }
  }
  tiles[i] = 0;
}

fn slide(i: int) {
  if solved() || toward(i, gap()) == 0 { return; }
  shift(i);
  moves += 1;
}

// Random slides from the solved order, so it can be solved; one more if it came back solved.
fn shuffle() {
  for i in 0..16 { tiles[i] = (i + 1) % 16; }
  repeat 300 { shift(random(16)); }
  if solved() { shift(14); }
  moves = 0;
}

fn tint(i: int) -> int {
  if tiles[i] == i + 1 { return 2; }
  return 4;
}

fn scene() {
  for i in 0..16 {
    if tiles[i] != 0 {
      rect((i % 4) * 30 + 1, (i / 4) * 30 + 1, 28, 28, tint(i));
      text(tiles[i], (i % 4) * 30 + 15, (i / 4) * 30 + 15, 12, 9);
    }
  }
}

