// Asteroids: left and right turn the ship, space (or Fire) shoots; big rocks split in two, small
// ones vanish; clear them all for the next level; a rock on the ship ends it.
// icon: fill 12 3 18 19 12 15 6 19 ring 5 6 3 dot 19 5 2
state ways = [0, 1, 1, 1, 0, -1, -1, -1];   // the eight ways across, from up turning right
state wayd = [-1, -1, 0, 1, 1, 1, 0, -1];   // and down
state face = 0;                             // the way the ship faces
state rx = [0; 0];                          // the rocks: top-left square, way, size
state ry = [0; 0];
state vx = [0; 0];
state vy = [0; 0];
state size = [0; 0];
state sx = 0;                               // the shot, flying while live
state sy = 0;
state sd = 0;
state live = false;
state ticks = 0;                            // 100 ms ticks since the level began
state score = 0;
state level = 1;
state speed = 0;                            // 100 while a game runs, else 0
state over = false;

fn pace() -> int { return max(100, 600 - 100 * level); }

fn rock(x: int, y: int, dx: int, dy: int, n: int) {
  push(rx, x);
  push(ry, y);
  push(vx, dx);
  push(vy, dy);
  push(size, n);
}

fn wave() {
  clear(rx);
  clear(ry);
  clear(vx);
  clear(vy);
  clear(size);
  rock(1, 1, 1, 0, 2);
  if level > 1 { rock(12, 4, -1, 0, 2); }
  live = false;
  ticks = 0;
}

// Whether rock k covers (x, y), around the edges.
fn covers(k: int, x: int, y: int) -> bool {
  return (x - rx[k] + 16) % 16 < size[k] && (y - ry[k] + 12) % 12 < size[k];
}

// The shot on a rock: both vanish; a big one leaves two small ones.
fn hit() {
  for k in 0..len(rx) {
    if live && covers(k, sx, sy) {
      live = false;
      if size[k] == 2 {
        score += 20;
        rock(rx[k], ry[k], vx[k], -1, 1);
        rock((rx[k] + 1) % 16, (ry[k] + 1) % 12, vx[k], 1, 1);
      } else {
        score += 50;
      }
      remove(rx, k);
      remove(ry, k);
      remove(vx, k);
      remove(vy, k);
      remove(size, k);
      if len(rx) == 0 {
        level += 1;
        wave();
      }
      return;
    }
  }
}

fn drift() {
  for k in 0..len(rx) {
    rx[k] = (rx[k] + vx[k] + 16) % 16;
    ry[k] = (ry[k] + vy[k] + 12) % 12;
    if covers(k, 7, 5) {
      over = true;
      speed = 0;
    }
  }
  hit();
}

fn start() {
  score = 0;
  level = 1;
  face = 0;
  over = false;
  wave();
  speed = 100;
}

fn fire() {
  if speed > 0 && !live {
    sd = face;
    sx = 7 + ways[sd];
    sy = 5 + wayd[sd];
    live = true;
    hit();
  }
}

fn turn(d: int) {
  if speed > 0 { face = (face + d + 8) % 8; }
}

every speed {
  ticks += 1;
  if live {
    sx += ways[sd];
    sy += wayd[sd];
    live = sx >= 0 && sx < 16 && sy >= 0 && sy < 12;
    hit();
  }
  // A level just begun (ticks back at 0) waits a whole drift.
  if ticks > 0 && ticks % (pace() / 100) == 0 { drift(); }
}

on key "left" { turn(-1); }
on key "right" { turn(1); }
on key "space" { fire(); }

// Big rocks purple, small ones red.
fn tint(n: int) -> int {
  if n == 2 { return 5; }
  return 1;
}

fn scene() {
  let cells = [-1; 192];
  cells[(5 + wayd[face]) * 16 + 7 + ways[face]] = 6;
  for k in 0..len(rx) {
    for i in 0..size[k] {
      for j in 0..size[k] { cells[((ry[k] + j) % 12) * 16 + (rx[k] + i) % 16] = tint(size[k]); }
    }
  }
  if live { cells[sy * 16 + sx] = 3; }
  cells[5 * 16 + 7] = 2;
  pixels(cells, 0, 0, 16, 10);
  if over { text("Game over", 80, 30, 16, 11); }
}

