// Asteroids: left and right turn the ship, up thrusts (it keeps its speed), space (or Fire)
// shoots; past an edge things come back at the other side; a rock on the ship costs one of 3 lives.
// icon: fill 12 3 18 19 12 15 6 19 line 12 17 12 22 dot 19 5 2
state ways = [0, 1, 0, -1];         // up, right, down, left: across
state wayd = [-1, 0, 1, 0];         // and down
state face = 0;                     // the way the ship faces
state px = 7;                       // the ship's square and speed
state py = 5;
state vx = 0;
state vy = 0;
state rx = [0, 15, 7, 2];           // the rocks: square, way, and whether each is left
state ry = [1, 5, 11, 0];
state rdx = [1, -1, 0, 1];
state rdy = [0, 0, -1, 1];
state rock = [false, false, false, false];
state sx = 0;                       // the shot, flying while live
state sy = 0;
state sd = 0;
state live = false;
state ticks = 0;                    // 100 ms ticks since Start
state score = 0;
state lives = 3;
state speed = 0;                    // 100 while a game runs, else 0
state won = false;
state over = false;

fn home() {
  px = 7;
  py = 5;
  vx = 0;
  vy = 0;
  face = 0;
}

fn start() {
  rx = [0, 15, 7, 2];
  ry = [1, 5, 11, 0];
  rock = [true, true, true, true];
  home();
  live = false;
  ticks = 0;
  score = 0;
  lives = 3;
  won = false;
  over = false;
  speed = 100;
}

fn left() -> int {
  let n = 0;
  for k in 0..4 {
    if rock[k] { n += 1; }
  }
  return n;
}

fn end() {
  if lives == 0 {
    over = true;
    speed = 0;
  } else if left() == 0 {
    won = true;
    speed = 0;
  }
}

// The shot on a rock: both vanish.
fn hit() {
  for k in 0..4 {
    if live && rock[k] && rx[k] == sx && ry[k] == sy {
      rock[k] = false;
      live = false;
      score += 10;
    }
  }
  end();
}

// A rock on the ship: it vanishes, and the ship loses a life and starts again.
fn crash() {
  for k in 0..4 {
    if rock[k] && rx[k] == px && ry[k] == py {
      rock[k] = false;
      lives -= 1;
      home();
    }
  }
  end();
}

fn fire() {
  if speed > 0 && !live {
    sd = face;
    sx = (px + ways[sd] + 16) % 16;
    sy = (py + wayd[sd] + 12) % 12;
    live = true;
    hit();
  }
}

fn turn(d: int) {
  if speed > 0 { face = (face + d + 4) % 4; }
}

fn thrust() {
  if speed > 0 {
    vx = min(2, max(-2, vx + ways[face]));
    vy = min(2, max(-2, vy + wayd[face]));
  }
}

every speed {
  ticks += 1;
  if live {
    sx += ways[sd];
    sy += wayd[sd];
    live = sx >= 0 && sx < 16 && sy >= 0 && sy < 12;
    hit();
  }
  if speed > 0 && ticks % 2 == 0 {
    px = (px + vx + 16) % 16;
    py = (py + vy + 12) % 12;
    crash();
  }
  if speed > 0 && ticks % 4 == 0 {
    for k in 0..4 {
      rx[k] = (rx[k] + rdx[k] + 16) % 16;
      ry[k] = (ry[k] + rdy[k] + 12) % 12;
    }
    crash();
    hit();
  }
}

on key "left" { turn(-1); }
on key "right" { turn(1); }
on key "up" { thrust(); }
on key "space" { fire(); }

fn scene() {
  let cells = [-1; 192];
  cells[((py + wayd[face] + 12) % 12) * 16 + (px + ways[face] + 16) % 16] = 6;
  for k in 0..4 {
    if rock[k] { cells[ry[k] * 16 + rx[k]] = 5; }
  }
  if live { cells[sy * 16 + sx] = 3; }
  cells[py * 16 + px] = 2;
  pixels(cells, 0, 0, 16, 10);
  if over { text("Game over", 80, 30, 16, 11); }
  if won { text("You win", 80, 30, 16, 11); }
}

