// Flappy with levels: space, up or a tap lifts the bird 2 squares; fly through the gaps, which
// narrow every 3 pipes passed; a crash costs one of 3 lives.
// icon: ring 8 12 5 dot 10 11 2 fill 16 2 21 2 21 7 16 7 fill 16 15 21 15 21 22 16 22
state by = 6;                   // the bird's row; its column is 4
state px = [0; 0];              // the pipes: column, the gap's top row and its size
state pg = [0; 0];
state pn = [0; 0];
state tops = [3, 6, 4, 2, 5];
state made = 0;                 // pipes made this game
state score = 0;
state level = 1;
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state over = false;

fn pipe() {
  push(px, 15);
  push(pg, tops[made % 5]);
  push(pn, max(2, 5 - level));
  made += 1;
}

// The bird back at row 6, and one new pipe.
fn again() {
  by = 6;
  clear(px);
  clear(pg);
  clear(pn);
  pipe();
}

fn start() {
  made = 0;
  score = 0;
  level = 1;
  lives = 3;
  over = false;
  again();
  speed = 150;
}

// On a pipe or below the bottom: a life lost, then again from row 6, or Game over.
fn check() {
  let hit = by > 11;
  for i in 0..len(px) {
    if px[i] == 4 && (by < pg[i] || by >= pg[i] + pn[i]) { hit = true; }
  }
  if hit {
    lives -= 1;
    if lives == 0 {
      over = true;
      speed = 0;
    } else {
      again();
    }
  }
}

fn lift() {
  if speed > 0 {
    by = max(0, by - 2);
    check();
  }
}

every speed {
  by += 1;
  for i in 0..len(px) {
    px[i] -= 1;
    if px[i] == 3 {
      score += 1;
      if score % 3 == 0 { level += 1; }
    }
  }
  if px[0] < 0 {
    remove(px, 0);
    remove(pg, 0);
    remove(pn, 0);
  }
  if px[len(px) - 1] == 9 { pipe(); }
  check();
}

