// River: the arrows (or a tap beside the frog) hop from log to log to the far bank; a log carries
// the frog along; the water, or the board's edge, costs one of 3 lives; cross three times to win.
// icon: fill 2 14 22 14 22 18 2 18 fill 8 6 16 6 16 12 8 12 dot 9 4 2 dot 15 4 2
state river = [0; 64];          // rows 1 to 4, 16 squares each: 1 a log
state fx = 7;                   // the frog
state fy = 5;
state ticks = 0;                // 200 ms ticks since Start
state crossed = 0;
state score = 0;
state lives = 3;
state speed = 0;                // 200 while a game runs, else 0
state won = false;
state over = false;

// A river row's way, and how many ticks between its moves.
fn way(r: int) -> int {
  if r == 4 || r == 2 { return 1; }
  return -1;
}

fn beat(r: int) -> int {
  if r == 3 { return 3; }
  if r == 2 { return 1; }
  return 2;
}

fn at(x: int, y: int) -> int { return (y - 1) * 16 + x; }

fn logs(r: int, a: int, b: int) {
  for c in a..b + 1 { river[at(c, r)] = 1; }
}

fn start() {
  for i in 0..64 { river[i] = 0; }
  logs(4, 0, 2);
  logs(4, 8, 10);
  logs(3, 3, 6);
  logs(3, 11, 13);
  logs(2, 1, 2);
  logs(2, 6, 7);
  logs(2, 11, 12);
  logs(1, 4, 7);
  logs(1, 12, 14);
  fx = 7;
  fy = 5;
  ticks = 0;
  crossed = 0;
  score = 0;
  lives = 3;
  won = false;
  over = false;
  speed = 200;
}

fn lose() {
  lives -= 1;
  fx = 7;
  fy = 5;
  if lives == 0 {
    over = true;
    speed = 0;
  }
}

fn hop(dx: int, dy: int) {
  let nx = fx + dx;
  let ny = fy + dy;
  if speed == 0 || nx < 0 || nx > 15 || ny > 5 { return; }
  fx = nx;
  fy = ny;
  if fy == 0 {
    crossed += 1;
    score += 10;
    fx = 7;
    fy = 5;
    if crossed == 3 {
      won = true;
      speed = 0;
    }
  } else if fy < 5 && river[at(fx, fy)] == 0 {
    lose();
  }
}

// Row r moves its logs one square its way, and the frog with them.
fn flow(r: int) {
  let d = way(r);
  let line = [0; 16];
  for c in 0..16 { line[(c + d + 16) % 16] = river[at(c, r)]; }
  for c in 0..16 { river[at(c, r)] = line[c]; }
  if fy == r {
    fx += d;
    if fx < 0 || fx > 15 { lose(); }
  }
}

every speed {
  ticks += 1;
  for r in 1..5 {
    if speed > 0 && ticks % beat(r) == 0 { flow(r); }
  }
}

