// Platformer: left and right run, up or space jumps (or tap beside the player, and Jump); take
// the coins and reach the green door, two levels; a fall into a pit costs one of 3 lives.
// icon: fill 2 18 22 18 22 22 2 22 fill 5 9 11 9 11 15 5 15 fill 14 11 20 11 20 17 14 17 dot 18 5 2
state world = [0; 192];   // 16 x 12 squares, row by row: 0 air, 8 block, 3 coin, 2 door
state px = 0;             // the player's square
state py = 10;
state rise = 0;           // steps of a jump left to rise
