state lives = 3;
state speed = 0;          // ms a step; 0 while no game runs
state won = false;
state over = false;

fn at(x: int, y: int) -> int { return y * 16 + x; }

// Whether (x, y) stops the player: a block, or past a side or the top; below the bottom is open.
fn solid(x: int, y: int) -> bool {
  if x < 0 || x > 15 || y < 0 { return true; }
  if y > 11 { return false; }
  return world[at(x, y)] == 8;
}

fn put(x: int, y: int, k: int) { world[at(x, y)] = k; }

// The level's squares, and the player at its start.
fn build() {
  for i in 0..192 { world[i] = 0; }
  for c in 0..16 { put(c, 11, 8); }
  if level == 1 {
    put(6, 9, 8);
    put(6, 10, 8);
    put(3, 10, 3);
    put(9, 10, 3);
  } else {
    put(5, 11, 0);
    put(6, 11, 0);
    for r in 8..11 { put(11, r, 8); }
    put(5, 8, 3);
    put(13, 10, 3);
  }
  put(15, 10, 2);
  px = 0;
  py = 10;
  rise = 0;
}

fn start() {
  level = 1;
  coins = 0;
  lives = 3;
  won = false;
  over = false;
  build();
  speed = 100;
}

// What the player's square holds: a coin is taken; the door leads on, or wins.
fn touch() {
  let k = world[at(px, py)];
  if k == 3 {
    coins += 1;
    put(px, py, 0);
  } else if k == 2 && level == 2 {
    won = true;
    speed = 0;
  } else if k == 2 {
    level += 1;
    build();
  }
}

fn walk(d: int) {
  if speed > 0 && !solid(px + d, py) {
    px += d;
    touch();
  }
}

fn jump() {
  if speed > 0 && solid(px, py + 1) { rise = 3; }
}

every speed {
  if rise > 0 && !solid(px, py - 1) {
    py -= 1;
    rise -= 1;
  } else {
    rise = 0;
    if !solid(px, py + 1) { py += 1; }
  }
  if py <= 11 {
    touch();
  } else {
    lives -= 1;
    px = 0;
    py = 10;
    if lives == 0 {
      over = true;
      speed = 0;
    }
  }
}

