  if (bx + dx == 0 && covers(me, by + dy)) || (bx + dx == 15 && covers(ai, by + dy)) { dx = -dx; }
  bx += dx;
  by += dy;
  if bx == 0 {
    cpu += 1;
    serve(-1);
  } else if bx == 15 {
    you += 1;
    serve(1);
  }
  if you == 3 { result = "You win"; }
  if cpu == 3 { result = "You lose"; }
  if result != "" {
    speed = 0;
  } else if steps % 2 == 0 && by < ai + 1 {
    ai = max(0, ai - 1);
  } else if steps % 2 == 0 && by > ai + 1 {
    ai = min(9, ai + 1);
  }
