  result = "";
  serve(-1);
  speed = 100;
}

// Turns the ball's speed up or down if it would take it past the top or the bottom.
fn walls() {
  if by + vy < 0 || by + vy > 11 { vy = -vy; }
}

// The ball meets the paddle whose top row is top: back across, aimed by the square it meets.
fn meet(top: int) {
  let k = by + vy - top;
  if k >= 0 && k < 4 {
    dx = -dx;
    vy = spin[k];
    walls();
  }
}

fn steer(d: int) {
  if speed > 0 { me = min(8, max(0, me + d)); }
}

every speed {
  walls();
  if bx + dx == 0 {
    meet(me);
  } else if bx + dx == 15 {
    meet(ai);
  }
  bx += dx;
  by += vy;
  if bx == 0 {
    cpu += 1;
    serve(-1);
  } else if bx == 15 {
    you += 1;
    serve(1);
  }
  if you == 5 { result = "You win"; }
  if cpu == 5 { result = "You lose"; }
  if result != "" {
    speed = 0;
  } else if by < ai + 1 {
    ai = max(0, ai - 1);
  } else if by > ai + 2 {
    ai = min(8, ai + 1);
  }
}

on key "up" { steer(-1); }
on key "down" { steer(1); }

