  let cells = [-1; 192];
  for i in 0..4 {
    cells[(me + i) * 16] = 4;
    cells[(ai + i) * 16 + 15] = 1;
  }
  cells[by * 16 + bx] = 3;
  pixels(cells, 0, 0, 16, 10);
  if result != "" { text(result, 80, 30, 16, 11); }
}

