// the arrows walk and climb (or tap beside the player); a barrel costs one of 3 lives.
// icon: fill 2 19 22 19 22 21 2 21 fill 2 9 22 9 22 11 2 11 line 6 11 6 19 line 10 11 10 19 ring 17 15 3
state bx = [0; 0];          // the barrels: square, way, and whether each is falling
