// Tower: the player bounces by itself; left and right (or a tap beside it) steer it onto the
// platforms above; the tower moves up as it climbs; falling off the bottom ends it.
// icon: fill 3 19 21 19 21 22 3 22 fill 13 12 21 12 21 14 13 14 fill 3 5 11 5 11 7 3 7 fill 8 14 12 14 12 18 8 18
state starts = [1, 5, 2, 6, 3, 7, 0, 4];   // the platforms' first columns, from height 3 up
