// Whether (x, h) is the ground or a platform: platforms every 3rd height, 3 squares wide.
fn solid(x: int, h: int) -> bool {
  if h == 0 { return true; }
  if h < 0 || h % 3 != 0 { return false; }
  let c = starts[(h / 3 - 1) % 8];
  return x >= c && x < c + 3;
}

fn start() {
  px = 4;
  ph = 1;
  rise = 0;
  base = 0;
  best = 1;
  over = false;
  speed = 150;
