// Chess for two: New game sets the pieces up; tap one of yours, then where it goes. Legal moves
// only, check and checkmate; a pawn on the last row becomes a queen. Without: castling, en passant.
// icon: dot 12 6 4 fill 9 10 15 10 18 21 6 21
state b = [0; 64];        // row by row from Black's side: 0 empty, 1 pawn, 2 knight, 3 bishop,
                          // 4 rook, 5 queen, 6 king; White's above 0, Black's below
state turn = 0;           // 1 White to move, -1 Black, 0 no game
state pick = -1;          // the square picked, -1 none
state check = false;      // the side to move is in check
state result = "";        // how the game ended

fn sgn(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// The piece on (c, r) once the piece on f has gone to t (f and t -1: the board as it is); 99
// off the board.
fn on(c: int, r: int, f: int, t: int) -> int {
  if c < 0 || c > 7 || r < 0 || r > 7 { return 99; }
  let i = r * 8 + c;
  if i == t { return b[f]; }
  if i == f { return 0; }
  return b[i];
}

// Whether side `by` attacks square s once f has gone to t.
fn hit(s: int, by: int, f: int, t: int) -> bool {
  let c = s % 8;
  let r = s / 8;
  let nx = [1, 2, 2, 1, -1, -2, -2, -1];
  let ny = [-2, -1, 1, 2, 2, 1, -1, -2];
  let dx = [1, -1, 0, 0, 1, 1, -1, -1];     // four straight ways, then four diagonal
  let dy = [0, 0, 1, -1, 1, -1, 1, -1];
  for k in 0..8 {
    if on(c + nx[k], r + ny[k], f, t) == 2 * by { return true; }
    if on(c + dx[k], r + dy[k], f, t) == 6 * by { return true; }
    let open = true;
    for d in 1..8 {
      if open {
        let p = on(c + dx[k] * d, r + dy[k] * d, f, t);
        if p != 0 {
          open = false;
          if p == 5 * by || p == (4 - k / 4) * by { return true; }
        }
      }
    }
  }
  return on(c - 1, r + by, f, t) == by || on(c + 1, r + by, f, t) == by;
}

// Whether side's king is attacked once f has gone to t.
fn exposed(side: int, f: int, t: int) -> bool {
  for i in 0..64 {
    if on(i % 8, i / 8, f, t) == 6 * side { return hit(i, -side, f, t); }
  }
  return false;
}

// Whether nothing stands between f and t, on a line across, down or diagonal.
fn free(f: int, t: int) -> bool {
  let sx = sgn(t % 8 - f % 8);
  let sy = sgn(t / 8 - f / 8);
  let n = max(abs(t % 8 - f % 8), abs(t / 8 - f / 8));
  for k in 1..n {
    if b[f + (sy * 8 + sx) * k] != 0 { return false; }
  }
  return true;
}

// Whether the piece on f may go to t the way it moves, its own king aside.
fn can(f: int, t: int) -> bool {
  let side = sgn(b[f]);
  if side == 0 || sgn(b[t]) == side { return false; }
  let dx = t % 8 - f % 8;
  let dy = t / 8 - f / 8;
  let ax = abs(dx);
  let ay = abs(dy);
  let k = abs(b[f]);
  if k == 1 {
    if ax == 1 && dy == -side { return b[t] != 0; }
    if dx != 0 || b[t] != 0 { return false; }
    if dy == -side { return true; }
    return dy == -2 * side && (f / 8 == 1 || f / 8 == 6) && free(f, t);
  }
  if k == 2 { return ax * ay == 2; }
  if k == 6 { return max(ax, ay) == 1; }
  let straight = dx == 0 || dy == 0;
  if k == 3 && ax != ay { return false; }
  if k == 4 && !straight { return false; }
  if k == 5 && ax != ay && !straight { return false; }
  return free(f, t);
}

fn legal(f: int, t: int) -> bool { return can(f, t) && !exposed(sgn(b[f]), f, t); }

// Whether side has no legal move.
fn stuck(side: int) -> bool {
  for f in 0..64 {
    if sgn(b[f]) == side {
      for t in 0..64 {
        if legal(f, t) { return false; }
      }
    }
  }
  return true;
}

fn setup() {
  let back = [4, 2, 3, 5, 6, 3, 2, 4];
  for c in 0..8 {
    b[c] = -back[c];
    b[8 + c] = -1;
    for r in 2..6 { b[r * 8 + c] = 0; }
    b[48 + c] = 1;
    b[56 + c] = back[c];
  }
  turn = 1;
  pick = -1;
  check = false;
  result = "";
}

fn go(f: int, t: int) {
  b[t] = b[f];
  b[f] = 0;
  if abs(b[t]) == 1 && (t < 8 || t >= 56) { b[t] = 5 * turn; }
  turn = -turn;
  pick = -1;
  check = exposed(turn, -1, -1);
  if stuck(turn) {
    if !check { result = "Stalemate: a draw"; }
    if check && turn < 0 { result = "Checkmate: White wins"; }
    if check && turn > 0 { result = "Checkmate: Black wins"; }
    turn = 0;
  }
}

fn tap(i: int) {
  if turn == 0 { return; }
  if sgn(b[i]) == turn {
    pick = i;
  } else if pick >= 0 && legal(pick, i) {
    go(pick, i);
  } else {
    pick = -1;
  }
}

fn status() -> string {
  if result != "" { return result; }
  if turn == 0 { return "Press New game"; }
  let s = "White to move";
  if turn < 0 { s = "Black to move"; }
  if check { return s + ": check"; }
  return s;
}

// The board, 8 x 8 squares of 20 units, dark ones gray; White's pieces yellow, Black's blue.
fn scene() {
  let names = ["", "P", "N", "B", "R", "Q", "K"];
  for i in 0..64 {
    let px = (i % 8) * 20;
    let py = (i / 8) * 20;
    if (i % 8 + i / 8) % 2 == 1 { rect(px, py, 20, 20, 8); }
    if b[i] != 0 {
      let tint = 3;
      if b[i] < 0 { tint = 4; }
      circle(px + 10, py + 10, 8, tint);
      text(names[abs(b[i])], px + 10, py + 10, 10, 9);
    }
    if i == pick { ring(px + 10, py + 10, 9, 2, 11); }
  }
}

