// Mate in one: three chess puzzles, White to move and mate. Tap a white piece, then where it goes;
// a move that does not mate puts the puzzle back. Next goes on once one is solved.
// icon: line 12 2 12 9 line 9 5 15 5 fill 8 11 16 11 18 21 6 21
state b = [0; 64];        // row by row from a8: 0 empty, 1 pawn, 2 knight, 3 bishop, 4 rook,
                          // 5 queen, 6 king; White's above 0, Black's below
// The puzzles: each piece's square and kind, puzzle after puzzle; each begins at first[n].
state sq = [62, 56, 57, 53, 54, 55, 6, 13, 14, 15, 17, 59, 0, 57, 28, 7, 6, 14, 15];
state pc = [6, 4, 4, 1, 1, 1, -6, -1, -1, -1, 6, 5, -6, 6, 2, -6, -4, -1, -1];
state first = [0, 10, 13, 19];
state level = -1;         // the puzzle shown, from 0; -1 before Start
state pick = -1;          // the square picked, -1 none
state solved = 0;
state mistakes = 0;
state note = "";          // what the last move was
state done = false;       // solved: nothing moves until Next

fn sgn(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// The piece on (c, r) once the piece on f has gone to t (f and t -1: the board as it is); 99
// off the board.
fn on(c: int, r: int, f: int, t: int) -> int {
  if c < 0 || c > 7 || r < 0 || r > 7 { return 99; }
  let i = r * 8 + c;
  if i == t { return b[f]; }
  if i == f { return 0; }
  return b[i];
}

// Whether side `by` attacks square s once f has gone to t.
fn hit(s: int, by: int, f: int, t: int) -> bool {
  let c = s % 8;
  let r = s / 8;
  let nx = [1, 2, 2, 1, -1, -2, -2, -1];
  let ny = [-2, -1, 1, 2, 2, 1, -1, -2];
  let dx = [1, -1, 0, 0, 1, 1, -1, -1];     // four straight ways, then four diagonal
  let dy = [0, 0, 1, -1, 1, -1, 1, -1];
  for k in 0..8 {
    if on(c + nx[k], r + ny[k], f, t) == 2 * by { return true; }
    if on(c + dx[k], r + dy[k], f, t) == 6 * by { return true; }
    let open = true;
    for d in 1..8 {
      if open {
        let p = on(c + dx[k] * d, r + dy[k] * d, f, t);
        if p != 0 {
          open = false;
          if p == 5 * by || p == (4 - k / 4) * by { return true; }
        }
      }
    }
  }
  return on(c - 1, r + by, f, t) == by || on(c + 1, r + by, f, t) == by;
}

// Whether side's king is attacked once f has gone to t.
fn exposed(side: int, f: int, t: int) -> bool {
  for i in 0..64 {
    if on(i % 8, i / 8, f, t) == 6 * side { return hit(i, -side, f, t); }
  }
  return false;
}

// Whether nothing stands between f and t, on a line across, down or diagonal.
fn free(f: int, t: int) -> bool {
  let sx = sgn(t % 8 - f % 8);
  let sy = sgn(t / 8 - f / 8);
  let n = max(abs(t % 8 - f % 8), abs(t / 8 - f / 8));
  for k in 1..n {
    if b[f + (sy * 8 + sx) * k] != 0 { return false; }
  }
  return true;
}

// Whether the piece on f may go to t the way it moves, its own king aside.
fn can(f: int, t: int) -> bool {
  let side = sgn(b[f]);
  if side == 0 || sgn(b[t]) == side { return false; }
  let dx = t % 8 - f % 8;
  let dy = t / 8 - f / 8;
  let ax = abs(dx);
  let ay = abs(dy);
  let k = abs(b[f]);
  if k == 1 {
    if ax == 1 && dy == -side { return b[t] != 0; }
    if dx != 0 || b[t] != 0 { return false; }
    if dy == -side { return true; }
    return dy == -2 * side && (f / 8 == 1 || f / 8 == 6) && free(f, t);
  }
  if k == 2 { return ax * ay == 2; }
  if k == 6 { return max(ax, ay) == 1; }
  let straight = dx == 0 || dy == 0;
  if k == 3 && ax != ay { return false; }
  if k == 4 && !straight { return false; }
  if k == 5 && ax != ay && !straight { return false; }
  return free(f, t);
}

fn legal(f: int, t: int) -> bool { return can(f, t) && !exposed(sgn(b[f]), f, t); }

// Whether side has no legal move.
fn stuck(side: int) -> bool {
  for f in 0..64 {
    if sgn(b[f]) == side {
      for t in 0..64 {
        if legal(f, t) { return false; }
      }
    }
  }
  return true;
}

// Puzzle n as it begins.
fn load(n: int) {
  level = n;
  for i in 0..64 { b[i] = 0; }
  for k in first[n]..first[n + 1] { b[sq[k]] = pc[k]; }
  pick = -1;
  done = false;
}

// White's move from f to t: a mate solves the puzzle, anything else puts it back.
fn play(f: int, t: int) {
  b[t] = b[f];
  b[f] = 0;
  pick = -1;
  if exposed(-1, -1, -1) && stuck(-1) {
    note = "Checkmate!";
    solved += 1;
    done = true;
  } else {
    note = "Try again";
    mistakes += 1;
    load(level);
  }
}

fn tap(i: int) {
  if level < 0 || done { return; }
  if b[i] > 0 {
    pick = i;
  } else if pick >= 0 && legal(pick, i) {
    play(pick, i);
  } else {
    pick = -1;
  }
}

fn title() -> string {
  if level < 0 { return "Press Start"; }
  return "Puzzle " + (level + 1) + " of 3: White to move and mate";
}

// The board, 8 x 8 squares of 20 units, dark ones gray; White's pieces yellow, Black's blue.
fn scene() {
  let names = ["", "P", "N", "B", "R", "Q", "K"];
  for i in 0..64 {
    let px = (i % 8) * 20;
    let py = (i / 8) * 20;
    if (i % 8 + i / 8) % 2 == 1 { rect(px, py, 20, 20, 8); }
    if b[i] != 0 {
      let tint = 3;
      if b[i] < 0 { tint = 4; }
      circle(px + 10, py + 10, 8, tint);
      text(names[abs(b[i])], px + 10, py + 10, 10, 9);
    }
    if i == pick { ring(px + 10, py + 10, 9, 2, 11); }
  }
}

label "Mate in one";
label title();
label note;
label "Solved: " + solved + "   Mistakes: " + mistakes;
canvas 160, 160, scene() { tap((y / 20) * 8 + x / 20); }
if level < 0 { button "Start" { load(0); } }
if done { button "Next" { note = ""; load((level + 1) % 3); } }

// Tower defense: tap the grass to build a tower (10 gold); Next wave sends six enemies down the
// path; each tower hits the one beside it farthest along. One that gets through costs a life.
// icon: fill 8 21 16 21 15 10 9 10 fill 6 3 18 3 18 10 6 10
state px = [0, 1, 2, 3, 4, 5, 6, 6, 6, 6, 7, 8, 9];   // the path's squares, in order
state py = [1, 1, 1, 1, 1, 1, 1, 2, 3, 4, 4, 4, 4];
state tower = [false; 60];  // 10 x 6 squares, row by row
state pos = [0; 0];         // each enemy on the board: how far along the path, oldest first
state hp = [0; 0];
state sent = 0;             // enemies of this wave sent so far
state steps = 0;            // steps since the wave was sent
state wave = 0;
state gold = 20;
state lives = 10;
state speed = 0;            // ms a step: 500 while a wave is on

fn onpath(i: int) -> bool {
  for k in 0..len(px) {
    if py[k] * 10 + px[k] == i { return true; }
  }
  return false;
}

// Whether enemy k is on one of the 8 squares around square i.
fn near(k: int, i: int) -> bool {
  return abs(px[pos[k]] - i % 10) <= 1 && abs(py[pos[k]] - i / 10) <= 1;
}

fn build(i: int) {
  if lives > 0 && !tower[i] && !onpath(i) && gold >= 10 {
    tower[i] = true;
    gold -= 10;
  }
}

// The tower on square i hits the enemy beside it farthest along.
fn shoot(i: int) {
  let best = -1;
  for k in 0..len(pos) {
    if hp[k] > 0 && near(k, i) && (best < 0 || pos[k] > pos[best]) { best = k; }
  }
  if best >= 0 {
    hp[best] -= 1;
    if hp[best] == 0 { gold += 3; }
  }
}

fn send() {
  wave += 1;
  sent = 0;
  steps = 0;
  speed = 500;
}

fn reset() {
  for i in 0..60 { tower[i] = false; }
  clear(pos);
  clear(hp);
  wave = 0;
  gold = 20;
  lives = 10;
  sent = 0;
  speed = 0;
}

// A step: the enemies move on (one past the end costs a life), one enters every second step
// until six have, the towers shoot, the fallen go; the wave ends when none is left.
every speed {
  steps += 1;
  let n = len(pos);
  for j in 0..n {
    let k = n - 1 - j;
    pos[k] += 1;
    if pos[k] >= len(px) {
      remove(pos, k);
      remove(hp, k);
      lives -= 1;
    }
  }
  if lives <= 0 {
    lives = 0;
    speed = 0;
    return;
  }
  if sent < 6 && steps == 1 + 2 * sent {
    push(pos, 0);
    push(hp, wave);
    sent += 1;
  }
  for i in 0..60 {
    if tower[i] { shoot(i); }
  }
  n = len(hp);
  for j in 0..n {
    let k = n - 1 - j;
    if hp[k] <= 0 { remove(pos, k); remove(hp, k); }
  }
  if sent == 6 && len(pos) == 0 { speed = 0; }
}

// The board, 10 x 6 squares of 16 units: grass green, the path gray, towers blue, enemies red.
fn scene() {
  let cells = [2; 60];
  for k in 0..len(px) { cells[py[k] * 10 + px[k]] = 8; }
  for i in 0..60 {
    if tower[i] { cells[i] = 4; }
  }
  for k in 0..len(pos) { cells[py[pos[k]] * 10 + px[pos[k]]] = 1; }
  pixels(cells, 0, 0, 10, 16);
  if lives == 0 { text("Game over", 80, 48, 16, 11); }
}

label "Tower defense";
label "Wave " + wave + "   Gold " + gold + "   Lives " + lives;
canvas 160, 96, scene() { build((y / 16) * 10 + x / 16); }
row {
  if speed == 0 && lives > 0 { button "Next wave" { send(); } }
  button "New game" { reset(); }
}

// Maze defense: tap to build a tower (5 gold) that walls the way and hits every enemy beside it;
// tap a tower to sell it. Enemies take the shortest way from the left edge to the right.
// icon: fill 3 3 9 3 9 15 3 15 fill 15 9 21 9 21 21 15 21 dot 12 18 3
state tower = [false; 63];  // 9 x 7 squares, row by row; enemies enter on 27 and leave from 35
state dist = [0; 63];       // steps to the exit going around the towers; -1: no way
state pos = [0; 0];         // each enemy's square
state hp = [0; 0];
state sent = 0;             // enemies of this wave sent so far
state steps = 0;            // steps since the wave was sent
state wave = 0;
state gold = 40;
state lives = 10;
state speed = 0;            // ms a step: 500 while a wave is on

// The square beside i the way k goes (0 right, 1 up, 2 down, 3 left); -1 off the board.
fn beside(i: int, k: int) -> int {
  let dx = [1, 0, 0, -1];
  let dy = [0, -1, 1, 0];
  let c = i % 9 + dx[k];
  let r = i / 9 + dy[k];
  if c < 0 || c > 8 || r < 0 || r > 6 { return -1; }
  return r * 9 + c;
}

// Each square's steps to the exit, around the towers: a search out from the exit.
fn flow() {
  for i in 0..63 { dist[i] = -1; }
  dist[35] = 0;
  let q = [35];
  let h = 0;
  repeat 63 {
    if h < len(q) {
      let i = q[h];
      h += 1;
      for k in 0..4 {
        let n = beside(i, k);
        if n >= 0 && !tower[n] && dist[n] < 0 {
          dist[n] = dist[i] + 1;
          push(q, n);
        }
      }
    }
  }
}

fn enemy(i: int) -> bool {
  for k in 0..len(pos) {
    if pos[k] == i { return true; }
  }
  return false;
}

// Whether the entrance or an enemy has no way out.
fn shut() -> bool {
  for k in 0..len(pos) {
    if dist[pos[k]] < 0 { return true; }
  }
  return dist[27] < 0;
}

fn tapped(i: int) {
  if lives == 0 { return; }
  if tower[i] {
    tower[i] = false;
    gold += 5;
  } else if i != 27 && i != 35 && gold >= 5 && !enemy(i) {
    tower[i] = true;
    flow();
    if shut() { tower[i] = false; } else { gold -= 5; }
  }
}

// Enemy k steps to the square beside it nearest the exit; right, up, down, left on a tie.
fn walk(k: int) {
  let best = -1;
  for d in 0..4 {
    let n = beside(pos[k], d);
    if n >= 0 && dist[n] >= 0 && (best < 0 || dist[n] < dist[best]) { best = n; }
  }
  if best >= 0 { pos[k] = best; }
}

fn reset() {
  for i in 0..63 { tower[i] = false; }
  clear(pos);
  clear(hp);
  wave = 0;
  gold = 40;
  lives = 10;
  speed = 0;
}

// A step: the enemies move (one on the exit leaves and costs a life), one enters each step until
// three have, every tower hits every enemy beside it, the fallen go.
every speed {
  steps += 1;
  flow();
  let n = len(pos);
  for j in 0..n {
    let k = n - 1 - j;
    if pos[k] == 35 {
      remove(pos, k);
      remove(hp, k);
      lives -= 1;
    } else {
      walk(k);
    }
  }
  if lives <= 0 {
    lives = 0;
    speed = 0;
    return;
  }
  if sent < 3 && steps == sent + 1 {
    push(pos, 27);
    push(hp, 10 * wave);
    sent += 1;
  }
  for i in 0..63 {
    if tower[i] {
      for k in 0..len(pos) {
        if abs(pos[k] % 9 - i % 9) <= 1 && abs(pos[k] / 9 - i / 9) <= 1 { hp[k] -= 1; }
      }
    }
  }
  n = len(hp);
  for j in 0..n {
    let k = n - 1 - j;
    if hp[k] <= 0 {
      remove(pos, k);
      remove(hp, k);
      gold += 2;
    }
  }
  if sent == 3 && len(pos) == 0 { speed = 0; }
}

// The board, 9 x 7 squares of 16 units: free squares green, towers blue, enemies red.
fn scene() {
  let cells = [2; 63];
  for i in 0..63 {
    if tower[i] { cells[i] = 4; }
  }
  for k in 0..len(pos) { cells[pos[k]] = 1; }
  pixels(cells, 0, 0, 9, 16);
  if lives == 0 { text("Game over", 72, 56, 16, 11); }
}

label "Maze defense";
label "Wave " + wave + "   Gold " + gold + "   Lives " + lives;
canvas 144, 112, scene() { tapped((y / 16) * 9 + x / 16); }
row {
  if speed == 0 && lives > 0 {
    button "Next wave" {
      wave += 1;
      sent = 0;
      steps = 0;
      speed = 500;
    }
  }
  button "New game" { reset(); }
}

// Farm: Start the season, pick Wheat or Corn, tap an empty plot to plant it and a ripe (yellow)
// one to sell it. A day a second; ripe crops rot after 3 days; the season ends after day 20.
// icon: line 12 22 12 8 fill 9 8 12 2 15 8 12 12 line 12 17 6 12 line 12 17 18 12
state plot = [0; 24];     // 6 x 4 plots, row by row: 0 empty, 1 wheat, 2 corn
state sown = [0; 24];     // the day each was planted
state day = 1;
state coins = 10;
state seed = 1;           // what a tap plants
state speed = 0;          // ms a day: 1000 while the season runs
state over = false;

fn cost(k: int) -> int {
  if k == 1 { return 2; }
  return 5;
}

fn price(k: int) -> int {
  if k == 1 { return 5; }
  return 12;
}

fn days(k: int) -> int {
  if k == 1 { return 3; }
  return 6;
}

fn name(k: int) -> string {
  if k == 1 { return "Wheat"; }
  return "Corn";
}

// How plot i is: 0 empty, 1 growing, 2 ripe, 3 rotten.
fn stage(i: int) -> int {
  if plot[i] == 0 { return 0; }
  let age = day - sown[i];
  if age < days(plot[i]) { return 1; }
  if age < days(plot[i]) + 3 { return 2; }
  return 3;
}

fn tap(i: int) {
  if speed == 0 { return; }
  let s = stage(i);
  if s == 0 && coins >= cost(seed) {
    plot[i] = seed;
    sown[i] = day;
    coins -= cost(seed);
  } else if s == 2 {
    coins += price(plot[i]);
    plot[i] = 0;
  } else if s == 3 {
    plot[i] = 0;
  }
}

fn start() {
  for i in 0..24 { plot[i] = 0; }
  day = 1;
  coins = 10;
  over = false;
  speed = 1000;
}

every speed {
  if day == 20 {
    speed = 0;
    over = true;
  } else {
    day += 1;
  }
}

// The field, 6 x 4 plots of 20 units: soil gray, growing green, ripe yellow, rotten red.
fn scene() {
  let tint = [8, 2, 3, 1];
  let cells = [0; 24];
  for i in 0..24 { cells[i] = tint[stage(i)]; }
  pixels(cells, 0, 0, 6, 20);
  if over { text("Season over", 60, 40, 12, 11); }
}

label "Farm";
label "Day " + day + "   Coins " + coins + "   Seed: " + name(seed);
canvas 120, 80, scene() { tap((y / 20) * 6 + x / 20); }
row {
  button "Wheat" { seed = 1; }
  button "Corn" { seed = 2; }
  if speed == 0 { button "Start" { start(); } }
}

// Farmer: the arrows (or a tap beside you) walk; space or Work plants (1 coin), waters or
// harvests (6 coins) where you stand, each for 1 energy; Sleep ends the day. Water a crop 3 days.
// icon: dot 12 5 3 line 12 8 12 16 line 7 11 17 11 line 12 16 8 21 line 12 16 16 21
state crop = [-1; 48];      // 8 x 6 squares, row by row: -1 bare soil, else days it was watered
state wet = [false; 48];    // watered today
state fx = 0;               // where the farmer stands
state fy = 0;
state day = 1;
state coins = 10;
state energy = 8;

fn walk(dx: int, dy: int) {
  fx = min(7, max(0, fx + dx));
  fy = min(5, max(0, fy + dy));
}

// Space: bare soil is planted, a ripe crop harvested, a growing one watered once a day.
fn work() {
  let i = fy * 8 + fx;
  if energy == 0 { return; }
  if crop[i] < 0 {
    if coins >= 1 {
      crop[i] = 0;
      coins -= 1;
      energy -= 1;
    }
  } else if crop[i] >= 3 {
    crop[i] = -1;
    coins += 6;
    energy -= 1;
  } else if !wet[i] {
    wet[i] = true;
    energy -= 1;
  }
}

// The night: what was watered grows a day.
fn sleep() {
  for i in 0..48 {
    if wet[i] {
      crop[i] += 1;
      wet[i] = false;
    }
  }
  day += 1;
  energy = 8;
}

// A tap on a square beside the farmer steps onto it.
fn step(c: int, r: int) {
  if abs(c - fx) + abs(r - fy) == 1 {
    fx = c;
    fy = r;
  }
}

// The field, 8 x 6 squares of 20 units: soil gray, growing green, watered blue, ripe yellow; the
// farmer a purple disc.
fn scene() {
  let cells = [8; 48];
  for i in 0..48 {
    if crop[i] >= 0 { cells[i] = 2; }
    if wet[i] { cells[i] = 4; }
    if crop[i] >= 3 { cells[i] = 3; }
  }
  pixels(cells, 0, 0, 8, 20);
  circle(fx * 20 + 10, fy * 20 + 10, 7, 5);
}

on key "left" { walk(-1, 0); }
on key "right" { walk(1, 0); }
on key "up" { walk(0, -1); }
on key "down" { walk(0, 1); }
on key "space" { work(); }

label "Farmer";
label "Day " + day + "   Coins " + coins + "   Energy " + energy;
canvas 160, 120, scene() { step(x / 20, y / 20); }
row {
  button "Work" { work(); }
  button "Sleep" { sleep(); }
}

// Rhythm: notes fall down four lanes to the line; press d, f, j or k (or tap the lane) as one
// reaches it: Perfect within 100 ms, Good within 250. A note let by is a Miss and ends the combo.
// icon: fill 3 4 9 4 9 8 3 8 fill 15 10 21 10 21 14 15 14 line 2 19 22 19
state times = [1000, 1500, 2000, 2500, 3000, 3500, 4000, 4500, 5000, 5500, 6000, 6500];
state lanes = [0, 1, 2, 3, 3, 2, 1, 0, 0, 2, 1, 3];
state done = [false; 12];   // judged already
state t = 0;                // ms since Start
state speed = 0;            // ms a tick: 50 while the song plays
state score = 0;
state combo = 0;
state best = 0;
state said = "";            // the last judgement
state over = false;

fn judge(word: string, points: int) {
  said = word;
  if points > 0 {
    score += points;
    combo += 1;
    best = max(best, combo);
  } else {
    combo = 0;
  }
}

// A press on a lane judges its note nearest in time, if one is within 250 ms.
fn hit(lane: int) {
  if speed == 0 { return; }
  let k = -1;
  for n in 0..12 {
    if lanes[n] == lane && !done[n] && abs(times[n] - t) <= 250 {
      if k < 0 || abs(times[n] - t) < abs(times[k] - t) { k = n; }
    }
  }
  if k >= 0 {
    done[k] = true;
    if abs(times[k] - t) <= 100 { judge("Perfect", 300); } else { judge("Good", 100); }
  }
}

fn start() {
  for n in 0..12 { done[n] = false; }
  t = 0;
  score = 0;
  combo = 0;
  best = 0;
  said = "";
  over = false;
  speed = 50;
}

every speed {
  t += 50;
  for n in 0..12 {
    if !done[n] && t - times[n] > 250 {
      done[n] = true;
      judge("Miss", 0);
    }
  }
  if t >= 7000 {
    speed = 0;
    over = true;
  }
}

// Four lanes 40 units wide; a note is 100 units above the line a second before its time.
fn scene() {
  for l in 1..4 { line(l * 40, 0, l * 40, 160, 1, 8); }
  rect(0, 138, 160, 4, 11);
  for n in 0..12 {
    let y = 140 - (times[n] - t) / 10;
    if !done[n] && y > -10 { rect(lanes[n] * 40 + 4, y - 4, 32, 8, 6); }
  }
  if over {
    text("Song over", 80, 60, 16, 11);
    text("Best combo " + best, 80, 84, 10, 9);
  }
}

on key "d" { hit(0); }
on key "f" { hit(1); }
on key "j" { hit(2); }
on key "k" { hit(3); }

label "Rhythm";
label "Score " + score + "   Combo " + combo;
label said;
canvas 160, 160, scene() { hit(x / 40); }
if speed == 0 { button "Start" { start(); } }

// Drum: notes scroll left to the mark; hit a red don with f, j or Don and a blue ka with d, k or
// Ka. Three levels, each faster; a Miss costs 2 health, a Hit gives 1 back. Clear all three.
// icon: ring 12 12 9 dot 12 12 4
state kinds = [0, 0, 1, 0, 1, 1, 0, 1];   // each level's notes: 0 don, 1 ka
state gaps = [800, 500, 350];            // ms between notes, level by level
state done = [false; 8];                 // judged already
state level = 0;                         // 0 before Start
state t = 0;                             // ms since the level began
state speed = 0;                         // ms a tick: 50 while a level plays
state score = 0;
state health = 6;
state said = "";                         // the last judgement
state result = "";                       // Failed, Cleared or You win

// When note n reaches the mark.
fn time(n: int) -> int { return 1000 + n * gaps[level - 1]; }

fn judge(hit: bool) {
  if hit {
    said = "Hit";
    score += 100;
    health = min(6, health + 1);
  } else {
    said = "Miss";
    health = max(0, health - 2);
    if health == 0 {
      speed = 0;
      result = "Failed";
    }
  }
}

// A press judges the note nearest in time, if one is within 150 ms: Hit if it is of its kind.
fn press(kind: int) {
  if speed == 0 { return; }
  let k = -1;
  for n in 0..8 {
    let d = abs(time(n) - t);
    if !done[n] && d <= 150 && (k < 0 || d < abs(time(k) - t)) { k = n; }
  }
  if k >= 0 {
    done[k] = true;
    judge(kinds[k] == kind);
  }
}

fn play(n: int) {
  level = n;
  for i in 0..8 { done[i] = false; }
  t = 0;
  health = 6;
  said = "";
  result = "";
  speed = 50;
}

every speed {
  t += 50;
  for n in 0..8 {
    if speed > 0 && !done[n] && t - time(n) > 150 {
      done[n] = true;
      judge(false);
    }
  }
  if speed > 0 && t >= time(7) + 1000 {
    speed = 0;
    if level == 3 { result = "You win"; } else { result = "Cleared"; }
  }
}

// The track: the mark at the left, each note 1 unit nearer for every 6 ms.
fn scene() {
  rect(0, 20, 200, 20, 8);
  ring(20, 30, 11, 2, 11);
  if level > 0 {
    for n in 0..8 {
      let px = 20 + (time(n) - t) / 6;
      if !done[n] && px < 210 { circle(px, 30, 8, 1 + kinds[n] * 3); }
    }
  }
  if result != "" { text(result, 100, 52, 12, 11); }
}

on key "f" { press(0); }
on key "j" { press(0); }
on key "d" { press(1); }
on key "k" { press(1); }

label "Drum";
label "Level " + level + "   Score " + score + "   Health " + health;
label said;
canvas 200, 60, scene();
row {
  button "Don" { press(0); }
  button "Ka" { press(1); }
  if speed == 0 && result == "Cleared" { button "Next" { play(level + 1); } }
  if speed == 0 && result != "Cleared" {
    button "Start" {
      score = 0;
      play(1);
    }
  }
}

// Box puzzle maker: pick Wall, Box, Goal, Player or Erase and tap squares to build a level; Play
// tries it with the arrows (or a tap beside you), pushing boxes onto goals; Edit goes back.
// icon: loop 4 8 14 8 14 18 4 18 line 4 8 14 18 line 14 8 4 18 ring 18 6 3
state ed = [0; 64];       // the level as built, 8 x 8: 0 floor, 1 wall, 2 box, 3 goal
state ex = 0;             // the player's square as built
state ey = 0;
state cell = [0; 64];     // the level in play: as built, and 4 a box on a goal
state px = 0;
state py = 0;
state tool = 1;           // what a tap puts: 0 erase, 1 wall, 2 box, 3 goal, 4 the player
state names = ["Erase", "Wall", "Box", "Goal", "Player"];
state playing = false;
state moves = 0;

// Building: the picked thing on square i; the player only onto floor or a goal.
fn put(i: int) {
  if i == ey * 8 + ex { return; }
  if tool == 4 {
    if ed[i] == 0 || ed[i] == 3 {
      ex = i % 8;
      ey = i / 8;
    }
  } else {
    ed[i] = tool;
  }
}

fn play() {
  for i in 0..64 { cell[i] = ed[i]; }
  px = ex;
  py = ey;
  moves = 0;
  playing = true;
}

fn solved() -> bool {
  let boxes = 0;
  for i in 0..64 {
    if cell[i] == 2 { return false; }
    if cell[i] == 4 { boxes += 1; }
  }
  return boxes > 0;
}

// Whether a box may be pushed onto (c, r): floor or a goal on the board.
fn open(c: int, r: int) -> bool {
  if c < 0 || c > 7 || r < 0 || r > 7 { return false; }
  return cell[r * 8 + c] == 0 || cell[r * 8 + c] == 3;
}

// A step of the player, pushing a box ahead if the square beyond it is open.
fn go(dx: int, dy: int) {
  if !playing || solved() { return; }
  let c = px + dx;
  let r = py + dy;
  if c < 0 || c > 7 || r < 0 || r > 7 { return; }
  let i = r * 8 + c;
  if cell[i] == 1 { return; }
  if cell[i] == 2 || cell[i] == 4 {
    if !open(c + dx, r + dy) { return; }
    let j = (r + dy) * 8 + c + dx;
    if cell[j] == 3 { cell[j] = 4; } else { cell[j] = 2; }
    if cell[i] == 4 { cell[i] = 3; } else { cell[i] = 0; }
  }
  px = c;
  py = r;
  moves += 1;
}

fn tapped(c: int, r: int) {
  if !playing {
    put(r * 8 + c);
  } else if abs(c - px) + abs(r - py) == 1 {
    go(c - px, r - py);
  }
}

// The board, 8 x 8 squares of 20 units: walls gray, boxes yellow, goals green, a box on a goal
// purple, the player blue; faint edges.
fn scene() {
  let tint = [-1, 8, 3, 2, 5];
  let cells = [-1; 64];
  for i in 0..64 {
    if playing { cells[i] = tint[cell[i]]; } else { cells[i] = tint[ed[i]]; }
  }
  if playing { cells[py * 8 + px] = 4; } else { cells[ey * 8 + ex] = 4; }
  pixels(cells, 0, 0, 8, 20);
  for k in 0..9 {
    line(k * 20, 0, k * 20, 160, 1, 8);
    line(0, k * 20, 160, k * 20, 1, 8);
  }
  if playing && solved() { text("Solved", 80, 80, 16, 11); }
}

on key "left" { go(-1, 0); }
on key "right" { go(1, 0); }
on key "up" { go(0, -1); }
on key "down" { go(0, 1); }

label "Sokoban maker";
if playing { label "Moves " + moves; } else { label "Tool: " + names[tool]; }
canvas 160, 160, scene() { tapped(x / 20, y / 20); }
if playing {
  button "Edit" { playing = false; }
} else {
  row {
    for k in 0..5 { button names[(k + 1) % 5] { tool = (k + 1) % 5; } }
  }
  button "Play" { play(); }
}

// Platform maker: pick Block, Coin, Spike, Goal or Start and tap to build a level; Play runs it:
// left and right walk, up jumps, coins count, spikes send you back, the goal ends it. Edit returns.
// icon: fill 2 17 22 17 22 21 2 21 fill 5 9 9 9 9 17 5 17 dot 17 9 3
state ed = [0; 96];       // 12 x 8 squares as built: 0 empty, 1 block, 2 coin, 3 spike, 4 goal
state sx = 0;             // the hero's starting square
state sy = 7;
state cell = [0; 96];     // the level in play
state hx = 0;             // the hero
state hy = 7;
state rise = 0;           // steps of a jump still to rise
state tool = 1;           // what a tap puts: 0 erase, 1 block, 2 coin, 3 spike, 4 goal, 5 start
state names = ["Erase", "Block", "Coin", "Spike", "Goal", "Start"];
state playing = false;
state done = false;
state speed = 0;          // ms a step: 150 while playing
state coins = 0;
state deaths = 0;

// A block, or off the board.
fn solid(c: int, r: int) -> bool {
  if c < 0 || c > 11 || r < 0 || r > 7 { return true; }
  return cell[r * 12 + c] == 1;
}

// Building: the picked thing on square i; the start only onto an empty one.
fn put(i: int) {
  if i == sy * 12 + sx { return; }
  if tool == 5 {
    if ed[i] == 0 {
      sx = i % 12;
      sy = i / 12;
    }
  } else {
    ed[i] = tool;
  }
}

fn play() {
  for i in 0..96 { cell[i] = ed[i]; }
  hx = sx;
  hy = sy;
  rise = 0;
  coins = 0;
  deaths = 0;
  done = false;
  playing = true;
  speed = 150;
}

// What the hero meets where it now is: a coin, a spike or the goal.
fn meet() {
  let i = hy * 12 + hx;
  if cell[i] == 2 {
    cell[i] = 0;
    coins += 1;
  } else if cell[i] == 3 {
    hx = sx;
    hy = sy;
    rise = 0;
    deaths += 1;
  } else if cell[i] == 4 {
    done = true;
    speed = 0;
  }
}

fn side(dx: int) {
  if speed > 0 && !solid(hx + dx, hy) {
    hx += dx;
    meet();
  }
}

fn jump() {
  if speed > 0 && solid(hx, hy + 1) { rise = 3; }
}

// A step: up while a jump rises (a block above ends it), else down if nothing holds it up.
every speed {
  if rise > 0 && solid(hx, hy - 1) {
    rise = 0;
  } else if rise > 0 {
    hy -= 1;
    rise -= 1;
    meet();
  } else if !solid(hx, hy + 1) {
    hy += 1;
    meet();
  }
}

// The board, 12 x 8 squares of 12 units: blocks gray, coins yellow, spikes red, the goal green,
// the hero (or its start) blue.
fn scene() {
  let tint = [-1, 8, 3, 1, 2];
  let cells = [-1; 96];
  for i in 0..96 {
    if playing { cells[i] = tint[cell[i]]; } else { cells[i] = tint[ed[i]]; }
  }
  if playing { cells[hy * 12 + hx] = 4; } else { cells[sy * 12 + sx] = 4; }
  pixels(cells, 0, 0, 12, 12);
  if done { text("Level complete", 72, 30, 12, 11); }
}

on key "left" { side(-1); }
on key "right" { side(1); }
on key "up" { jump(); }

label "Platform maker";
if playing { label "Coins " + coins + "   Deaths " + deaths; } else { label "Tool: " + names[tool]; }
canvas 144, 96, scene() { if !playing { put((y / 12) * 12 + x / 12); } }
if playing {
  row {
    button "Left" { side(-1); }
    button "Jump" { jump(); }
    button "Right" { side(1); }
  }
  button "Edit" {
    playing = false;
    speed = 0;
    done = false;
  }
} else {
  row {
    for k in 0..6 { button names[(k + 1) % 6] { tool = (k + 1) % 6; } }
  }
  button "Play" { play(); }
}

// Dungeon: the arrows (or a tap beside you) move you or hit a monster in the way; space waits.
// You see 2 squares around you; the potion heals 3; the stairs lead down to tougher monsters.
// icon: loop 4 4 20 4 20 20 4 20 dot 9 9 3 line 13 16 19 16 19 10
state seen = [false; 100];  // 10 x 10 squares, row by row: seen before
state mx = [3, 7];          // the monsters: where, and their HP (0: gone)
state my = [4, 2];
state mhp = [2, 3];
state px = 1;
state py = 1;
state hp = 10;
state floor = 1;
state potion = true;

fn wall(c: int, r: int) -> bool {
  return c == 0 || c == 9 || r == 0 || r == 9 || (c == 5 && r <= 7);
}

fn sgn(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

// The monster on (c, r), or -1.
fn monster(c: int, r: int) -> int {
  for k in 0..2 {
    if mhp[k] > 0 && mx[k] == c && my[k] == r { return k; }
  }
  return -1;
}

fn free(c: int, r: int) -> bool {
  return !wall(c, r) && monster(c, r) < 0 && (c != px || r != py);
}

fn near(c: int, r: int) -> bool { return abs(c - px) <= 2 && abs(r - py) <= 2; }

// What you see now stays seen.
fn look() {
  for i in 0..100 {
    if near(i % 10, i / 10) { seen[i] = true; }
  }
}

// Each monster within 3 squares hits you if it is beside you, else steps toward you.
fn monsters() {
  for k in 0..2 {
    if mhp[k] > 0 && hp > 0 && max(abs(mx[k] - px), abs(my[k] - py)) <= 3 {
      let ax = sgn(px - mx[k]);
      let ay = sgn(py - my[k]);
      if abs(mx[k] - px) + abs(my[k] - py) == 1 {
        hp -= 1;
      } else if ax != 0 && free(mx[k] + ax, my[k]) {
        mx[k] += ax;
      } else if ay != 0 && free(mx[k], my[k] + ay) {
        my[k] += ay;
      }
    }
  }
}

// A floor begins: the same map, nothing seen, the monsters tougher the deeper.
fn begin() {
  for i in 0..100 { seen[i] = false; }
  px = 1;
  py = 1;
  mx[0] = 3;
  my[0] = 4;
  mhp[0] = 1 + floor;
  mx[1] = 7;
  my[1] = 2;
  mhp[1] = 2 + floor;
  potion = true;
}

// A turn: a step, a hit or (0, 0) a wait; then the monsters.
fn act(dx: int, dy: int) {
  let c = px + dx;
  let r = py + dy;
  if hp == 0 || wall(c, r) { return; }
  look();
  let k = monster(c, r);
  if k >= 0 {
    mhp[k] -= 1;
  } else {
    px = c;
    py = r;
    if potion && c == 8 && r == 4 {
      potion = false;
      hp = min(10, hp + 3);
    }
    if c == 8 && r == 1 {
      floor += 1;
      begin();
      return;
    }
  }
  monsters();
}

// The board, 10 x 10 squares of 12 units; what was never seen is blank.
fn scene() {
  let cells = [0; 100];
  for i in 0..100 {
    let c = i % 10;
    let r = i / 10;
    if seen[i] || near(c, r) {
      cells[i] = 2;
      if wall(c, r) { cells[i] = 8; }
      if c == 8 && r == 1 { cells[i] = 3; }
      if potion && c == 8 && r == 4 { cells[i] = 5; }
      if monster(c, r) >= 0 { cells[i] = 1; }
      if c == px && r == py { cells[i] = 4; }
    }
  }
  pixels(cells, 0, 0, 10, 12);
  if hp == 0 { text("Game over", 60, 60, 16, 11); }
}

on key "left" { act(-1, 0); }
on key "right" { act(1, 0); }
on key "up" { act(0, -1); }
on key "down" { act(0, 1); }
on key "space" { act(0, 0); }

label "Dungeon";
label "HP " + hp + "   Floor " + floor;
canvas 120, 120, scene() {
  if abs(x / 12 - px) + abs(y / 12 - py) == 1 { act(x / 12 - px, y / 12 - py); }
}
button "New game" {
  hp = 10;
  floor = 1;
  begin();
}

// Torch escape: the arrows (or a tap beside you) walk, 1 oil a step; take the key, open the red
// door, reach the exit. Your torch lights 2 squares around you, 1 when low; at 0 oil it goes out.
// icon: fill 10 12 14 12 13 21 11 21 fill 12 3 16 8 12 11 8 8
state px = 1;               // you, on a 9 x 9 board
state py = 1;
state oil = 24;
state gold = 0;
state key = 0;              // 0 lying on its square, 1 carried, 2 used on the door
state coins = [true, true]; // the gold on 4,1 and on 3,7, not yet taken
state flask = true;
state end = "";             // You escaped, or Game over

fn wall(c: int, r: int) -> bool {
  return c == 0 || c == 8 || r == 0 || r == 8 || (r == 4 && c != 2) || (c == 5 && (r == 5 || r == 6));
}

// The color of what is on (c, r), you aside.
fn what(c: int, r: int) -> int {
  if wall(c, r) { return 8; }
  if c == 2 && r == 4 && key < 2 { return 1; }
  if c == 7 && r == 2 && key == 0 { return 6; }
  if (c == 4 && r == 1 && coins[0]) || (c == 3 && r == 7 && coins[1]) { return 3; }
  if c == 2 && r == 6 && flask { return 5; }
  if c == 7 && r == 5 { return 7; }
  return 2;
}

// A step: walls stop you, and the door unless you carry the key; then you take what is there.
fn step(dx: int, dy: int) {
  let c = px + dx;
  let r = py + dy;
  if end != "" || wall(c, r) { return; }
  if c == 2 && r == 4 && key < 2 {
    if key == 0 { return; }
    key = 2;
  }
  px = c;
  py = r;
  oil -= 1;
  if key == 0 && c == 7 && r == 2 { key = 1; }
  if coins[0] && c == 4 && r == 1 {
    coins[0] = false;
    gold += 1;
  }
  if coins[1] && c == 3 && r == 7 {
    coins[1] = false;
    gold += 1;
  }
  if flask && c == 2 && r == 6 {
    flask = false;
    oil = min(24, oil + 10);
  }
  if c == 7 && r == 5 {
    end = "You escaped";
  } else if oil <= 0 {
    end = "Game over";
  }
}

// How far the torch lights.
fn light() -> int {
  if oil > 10 { return 2; }
  if oil > 0 { return 1; }
  return 0;
}

fn carry() -> string {
  if key == 1 { return "   Key"; }
  return "";
}

// The board, 9 x 9 squares of 12 units: only what the torch lights shows.
fn scene() {
  let cells = [0; 81];
  let d = light();
  for i in 0..81 {
    if abs(i % 9 - px) <= d && abs(i / 9 - py) <= d { cells[i] = what(i % 9, i / 9); }
  }
  cells[py * 9 + px] = 4;
  pixels(cells, 0, 0, 9, 12);
  if end != "" { text(end, 54, 54, 12, 11); }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "up" { step(0, -1); }
on key "down" { step(0, 1); }

label "Torch escape";
label "Oil " + oil + "   Gold " + gold + carry();
canvas 108, 108, scene() {
  if abs(x / 12 - px) + abs(y / 12 - py) == 1 { step(x / 12 - px, y / 12 - py); }
}
button "New game" {
  px = 1;
  py = 1;
  oil = 24;
  gold = 0;
  key = 0;
  coins[0] = true;
  coins[1] = true;
  flask = true;
  end = "";
}
